463→// writeTranscriptBlobs writes redacted, chunked transcript blobs to entries.
464→// Returns the redacted transcript bytes so the caller can compute the content hash.
465→func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) ([]byte, error) {
466→	// Redact secrets before chunking
467→	redacted, err := redact.JSONLBytes(transcript)
468→	if err != nil {
469→		return nil, fmt.Errorf("failed to redact transcript: %w", err)
470→	}
471→
472→	chunks, err := agent.ChunkTranscript(ctx, redacted, agentType)
473→	if err != nil {
474→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
475→	}
476→
477→	for i, chunk := range chunks {
478→		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
479→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
480→		if err != nil {
481→			return nil, err
482→		}
483→		entries[chunkPath] = object.TreeEntry{
484→			Name: chunkPath,
485→			Mode: filemode.Regular,
486→			Hash: blobHash,
487→		}
488→	}
489→
490→	return redacted, nil
491→}
