493→// validateWriteOpts validates identifiers in WriteCommittedOptions.
494→func validateWriteOpts(opts WriteCommittedOptions) error {
495→	if opts.CheckpointID.IsEmpty() {
496→		return errors.New("invalid checkpoint options: checkpoint ID is required")
497→	}
498→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
499→		return fmt.Errorf("invalid checkpoint options: %w", err)
500→	}
501→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
502→		return fmt.Errorf("invalid checkpoint options: %w", err)
503→	}
504→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
505→		return fmt.Errorf("invalid checkpoint options: %w", err)
506→	}
507→	return nil
508→}
