472→func (s *GitStore) reaggregateFromEntries(basePath string, sessionCount int, entries map[string]object.TreeEntry) (int, []string, *agent.TokenUsage, error) {
473→	var totalCount int
474→	var allFiles []string
475→	var totalTokens *agent.TokenUsage
476→
477→	for i := range sessionCount {
478→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
479→		entry, exists := entries[path]
480→		if !exists {
481→			return 0, nil, nil, fmt.Errorf("session %d metadata not found at %s", i, path)
482→		}
483→		meta, err := s.readMetadataFromBlob(entry.Hash)
484→		if err != nil {
485→			return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
486→		}
487→		totalCount += meta.CheckpointsCount
488→		allFiles = mergeFilesTouched(allFiles, meta.FilesTouched)
489→		totalTokens = aggregateTokenUsage(totalTokens, meta.TokenUsage)
490→	}
491→
492→	return totalCount, allFiles, totalTokens, nil
493→}
