```go
// FlattenCheckpointEntries reads all entries from a checkpoint's shard path
// in the given root tree. Returns an empty map if the checkpoint doesn't exist.
func FlattenCheckpointEntries(repo *git.Repository, rootTreeHash plumbing.Hash, checkpointPath string) (map[string]object.TreeEntry, error) {
	entries := make(map[string]object.TreeEntry)
	if rootTreeHash == plumbing.ZeroHash {
		return entries, nil
	}

	rootTree, err := repo.TreeObject(rootTreeHash)
	if err != nil {
		if errors.Is(err, plumbing.ErrObjectNotFound) {
			return entries, nil
		}
		return nil, fmt.Errorf("failed to read root tree %s: %w", rootTreeHash, err)
	}

	subtree, err := rootTree.Tree(checkpointPath)
	if err != nil {
		return entries, nil //nolint:nilerr // Checkpoint doesn't exist yet
	}

	if err := FlattenTree(repo, subtree, checkpointPath, entries); err != nil {
		return nil, err
	}
	return entries, nil
}
```

Then update the existing method to delegate:

