package v2

import (
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// GitStore provides checkpoint storage operations for the v2 ref layout.
// It writes to two custom refs under refs/entire/:
//   - /main: permanent metadata + compact transcripts
//   - /full/current: active generation of raw transcripts
type GitStore struct {
	repo *git.Repository

	// maxCheckpointsPerGeneration overrides the rotation threshold for testing.
	// Zero means use checkpoint.DefaultMaxCheckpointsPerGeneration.
	maxCheckpointsPerGeneration int
}

// maxCheckpoints returns the effective rotation threshold.
func (s *GitStore) maxCheckpoints() int {
	if s.maxCheckpointsPerGeneration > 0 {
		return s.maxCheckpointsPerGeneration
	}
	return checkpoint.DefaultMaxCheckpointsPerGeneration
}

// NewGitStore creates a new v2 checkpoint store backed by the given git repository.
func NewGitStore(repo *git.Repository) *GitStore {
	return &GitStore{
		repo: repo,
	}
}

// ensureRef ensures that a custom ref exists, creating an orphan commit
// with an empty tree if it does not.
func (s *GitStore) ensureRef(refName plumbing.ReferenceName) error {
	_, err := s.repo.Reference(refName, true)
	if err == nil {
		return nil
	}

	emptyTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
	if err != nil {
		return fmt.Errorf("failed to build empty tree: %w", err)
	}

	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
	commitHash, err := checkpoint.CreateCommit(s.repo, emptyTreeHash, plumbing.ZeroHash, "Initialize v2 ref", authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create initial commit: %w", err)
	}

	ref := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(ref); err != nil {
		return fmt.Errorf("failed to set ref %s: %w", refName, err)
	}

	return nil
}

// getRefState returns the parent commit hash and root tree hash for a ref.
func (s *GitStore) getRefState(refName plumbing.ReferenceName) (parentHash, treeHash plumbing.Hash, err error) {
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("ref %s not found: %w", refName, err)
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit for ref %s: %w", refName, err)
	}

	return ref.Hash(), commit.TreeHash, nil
}

// updateRef creates a new commit on a ref with the given tree, updating the ref to point to it.
func (s *GitStore) updateRef(refName plumbing.ReferenceName, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) error {
	commitHash, err := checkpoint.CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create commit: %w", err)
	}

	ref := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(ref); err != nil {
		return fmt.Errorf("failed to update ref %s: %w", refName, err)
	}

	return nil
}
