177→// listArchivedGenerations returns the names of all archived generation refs
178→// (everything under V2FullRefPrefix matching the expected numeric format), sorted ascending.
179→func (s *V2GitStore) listArchivedGenerations() ([]string, error) {
180→	refs, err := s.repo.References()
181→	if err != nil {
182→		return nil, fmt.Errorf("failed to list references: %w", err)
183→	}
184→
185→	var archived []string
186→	err = refs.ForEach(func(ref *plumbing.Reference) error {
187→		name := ref.Name().String()
188→		if !strings.HasPrefix(name, paths.V2FullRefPrefix) {
189→			return nil
190→		}
191→		suffix := strings.TrimPrefix(name, paths.V2FullRefPrefix)
192→		if suffix == "current" || !generationRefPattern.MatchString(suffix) {
193→			return nil
194→		}
195→		archived = append(archived, suffix)
196→		return nil
197→	})
198→	if err != nil {
199→		return nil, fmt.Errorf("failed to iterate references: %w", err)
200→	}
201→
202→	sort.Strings(archived)
203→	return archived, nil
204→}
205→
206→// nextGenerationNumber returns the next sequential generation number for archiving.
207→// Scans existing archived refs and returns max+1. Returns 1 if no archives exist.
208→func (s *V2GitStore) nextGenerationNumber() (int, error) {
209→	archived, err := s.listArchivedGenerations()
210→	if err != nil {
211→		return 0, err
212→	}
213→
214→	var maxNum int64
215→	for _, name := range archived {
216→		n, parseErr := strconv.ParseInt(name, 10, 64)
217→		if parseErr != nil {
218→			continue // skip unparseable entries
219→		}
220→		if n > maxNum {
221→			maxNum = n
222→		}
223→	}
224→	return int(maxNum) + 1, nil
225→}
