227→// rotateGeneration archives the current /full/current generation and creates
228→// a fresh orphan. This is a 2-phase operation:
229→//
230→//  1. Archive: determine the next generation number, create a new ref pointing
231→//     to the current /full/current commit.
232→//  2. Reset: create a fresh orphan commit with an empty tree + seed generation.json,
233→//     point /full/current at it.
234→func (s *V2GitStore) rotateGeneration(ctx context.Context) error {
235→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
236→
237→	// Guard against concurrent rotation: if another instance already rotated,
238→	// /full/current will have fewer checkpoints than the threshold.
239→	gen, err := s.readGenerationFromRef(refName)
240→	if err != nil {
241→		return fmt.Errorf("rotation: failed to read /full/current: %w", err)
242→	}
243→	if len(gen.Checkpoints) < s.maxCheckpoints() {
244→		return nil
245→	}
246→
247→	currentRef, err := s.repo.Reference(refName, true)
248→	if err != nil {
249→		return fmt.Errorf("rotation: failed to read /full/current ref: %w", err)
250→	}
251→
252→	archiveNumber, err := s.nextGenerationNumber()
253→	if err != nil {
254→		return fmt.Errorf("rotation: failed to determine next generation number: %w", err)
255→	}
256→
257→	// Phase 1: Archive — create ref pointing to the current commit.
258→	// If the archive ref already exists, another instance already rotated — skip.
259→	archiveRefName := plumbing.ReferenceName(fmt.Sprintf("%s%0*d", paths.V2FullRefPrefix, generationRefWidth, archiveNumber))
260→	if _, refErr := s.repo.Reference(archiveRefName, true); refErr == nil {
261→		logging.Info(ctx, "rotation: archive ref already exists, skipping",
262→			slog.String("archive_ref", string(archiveRefName)),
263→		)
264→		return nil
265→	}
266→	archiveRef := plumbing.NewHashReference(archiveRefName, currentRef.Hash())
267→	if err := s.repo.Storer.SetReference(archiveRef); err != nil {
268→		return fmt.Errorf("rotation: failed to create archived ref %s: %w", archiveRefName, err)
269→	}
270→
271→	// Verify /full/current hasn't been advanced by another writer since we read it.
272→	// If it changed, abort — the archive ref is harmless (points to a valid commit)
273→	// and the next writer will trigger rotation again.
274→	postArchiveRef, err := s.repo.Reference(refName, true)
275→	if err != nil {
276→		return fmt.Errorf("rotation: failed to re-read /full/current: %w", err)
277→	}
278→	if postArchiveRef.Hash() != currentRef.Hash() {
279→		logging.Info(ctx, "rotation: /full/current changed during rotation, aborting reset")
280→		return nil
281→	}
282→
283→	// Phase 2: Create fresh orphan /full/current
284→	seedGen := GenerationMetadata{
285→		Checkpoints: []id.CheckpointID{},
286→	}
287→	seedEntries := make(map[string]object.TreeEntry)
288→	if err := s.writeGeneration(seedGen, seedEntries); err != nil {
289→		return fmt.Errorf("rotation: failed to build seed generation: %w", err)
290→	}
291→	seedTreeHash, err := BuildTreeFromEntries(s.repo, seedEntries)
292→	if err != nil {
293→		return fmt.Errorf("rotation: failed to build seed tree: %w", err)
294→	}
295→
296→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
297→	orphanCommitHash, err := CreateCommit(s.repo, seedTreeHash, plumbing.ZeroHash, "Start generation", authorName, authorEmail)
298→	if err != nil {
299→		return fmt.Errorf("rotation: failed to create orphan commit: %w", err)
300→	}
301→
302→	orphanRef := plumbing.NewHashReference(refName, orphanCommitHash)
303→	if err := s.repo.Storer.SetReference(orphanRef); err != nil {
304→		return fmt.Errorf("rotation: failed to reset /full/current: %w", err)
305→	}
306→
307→	logging.Info(ctx, "generation rotation complete",
308→		slog.Int("archived_generation", archiveNumber),
309→		slog.String("archive_ref", string(archiveRefName)),
310→	)
311→
312→	return nil
313→}
