243→// writeMainCheckpointEntries orchestrates writing session data to the /main ref.
244→// It mirrors GitStore.writeStandardCheckpointEntries but excludes raw transcript blobs.
245→// Returns the session index used, for coordination with writeCommittedFullTranscript.
246→func (s *V2GitStore) writeMainCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (int, error) {
247→	// Read existing summary to get current session count
248→	var existingSummary *CheckpointSummary
249→	metadataPath := basePath + paths.MetadataFileName
250→	if entry, exists := entries[metadataPath]; exists {
251→		existing, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
252→		if err == nil {
253→			existingSummary = existing
254→		}
255→	}
256→
257→	// Determine session index
258→	sessionIndex := s.gs.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
259→
260→	// Write session files (metadata and prompts — no transcript or content hash)
261→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
262→	sessionFilePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
263→	if err != nil {
264→		return 0, err
265→	}
266→
267→	// Build the sessions array
268→	var sessions []SessionFilePaths
269→	if existingSummary != nil {
270→		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
271→		copy(sessions, existingSummary.Sessions)
272→	} else {
273→		sessions = make([]SessionFilePaths, 1)
274→	}
275→	sessions[sessionIndex] = sessionFilePaths
276→
277→	// Write root CheckpointSummary
278→	if err := s.gs.writeCheckpointSummary(opts, basePath, entries, sessions); err != nil {
279→		return 0, err
280→	}
281→	return sessionIndex, nil
282→}
