369→// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
370→// Transcripts accumulate across checkpoints — each write splices into the existing
371→// tree. Generation metadata (generation.json) at the tree root is updated on every
372→// write with the new checkpoint ID and timestamps.
373→//
374→// sessionIndex is the session slot (0-based), determined by the caller to stay
375→// consistent with the /main ref's session numbering.
376→// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
377→func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
378→	transcript := opts.Transcript
379→	if len(transcript) == 0 && opts.TranscriptPath != "" {
380→		var readErr error
381→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
382→		if readErr != nil {
383→			transcript = nil
384→		}
385→	}
386→	if len(transcript) == 0 {
387→		return nil // No transcript to write
388→	}
389→
390→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
391→	if err := s.ensureRef(refName); err != nil {
392→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
393→	}
394→
395→	parentHash, rootTreeHash, err := s.getRefState(refName)
396→	if err != nil {
397→		return err
398→	}
399→
400→	basePath := opts.CheckpointID.Path() + "/"
401→	checkpointPath := opts.CheckpointID.Path()
402→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
403→
404→	// Read existing entries at this checkpoint's shard path
405→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
406→	if err != nil {
407→		return err
408→	}
409→
410→	// Clear existing entries at this session path before writing new ones
411→	for key := range entries {
412→		if strings.HasPrefix(key, sessionPath) {
413→			delete(entries, key)
414→		}
415→	}
416→
417→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, sessionPath, entries)
418→	if err != nil {
419→		return err
420→	}
421→
422→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
423→		return err
424→	}
425→
426→	// Splice checkpoint data into the root tree (preserves other checkpoints' transcripts)
427→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
428→	if err != nil {
429→		return err
430→	}
431→
432→	// Update generation.json at the tree root with the new checkpoint ID and timestamps.
433→	// This reads from the pre-splice root tree (to get existing metadata) and writes
434→	// into the post-splice tree (which already has the shard directories).
435→	gen, err := s.updateGenerationForWrite(rootTreeHash, opts.CheckpointID, time.Now().UTC())
436→	if err != nil {
437→		return fmt.Errorf("failed to update generation metadata: %w", err)
438→	}
439→	newTreeHash, err = s.addGenerationToRootTree(newTreeHash, gen)
440→	if err != nil {
441→		return fmt.Errorf("failed to add generation.json to tree: %w", err)
442→	}
443→
444→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
445→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
446→		return err
447→	}
448→
449→	// Check if rotation is needed after successful write.
450→	if len(gen.Checkpoints) >= s.maxCheckpoints() {
451→		if rotErr := s.rotateGeneration(ctx); rotErr != nil {
452→			logging.Warn(ctx, "generation rotation failed",
453→				slog.String("error", rotErr.Error()),
454→				slog.Int("checkpoint_count", len(gen.Checkpoints)),
455→			)
456→			// Non-fatal: rotation failure doesn't invalidate the write
457→		}
458→	}
459→
460→	return nil
461→}
