// Package v2 provides checkpoint storage operations for the v2 ref layout.
//
// Helper functions in this file are intentionally duplicated from
// checkpoint/committed.go. The v1 and v2 checkpoint stores may evolve
// independently, and the v1 code will be removed once the switch to v2
// is complete. Sharing via an internal package is not feasible due to
// import cycles (these functions reference types defined in the checkpoint
// package). See docs/superpowers/specs/2026-03-26-resume-v2-read-path.md.
package v2

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/entireio/cli/redact"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// flattenCheckpointEntries reads all entries from a checkpoint's shard path
// in the given root tree. Returns an empty map if the checkpoint doesn't exist.
// Duplicated from checkpoint.GitStore.flattenCheckpointEntries.
func flattenCheckpointEntries(repo *git.Repository, rootTreeHash plumbing.Hash, checkpointPath string) (map[string]object.TreeEntry, error) {
	entries := make(map[string]object.TreeEntry)
	if rootTreeHash == plumbing.ZeroHash {
		return entries, nil
	}

	rootTree, err := repo.TreeObject(rootTreeHash)
	if err != nil {
		if errors.Is(err, plumbing.ErrObjectNotFound) {
			return entries, nil // Tree doesn't exist yet
		}
		return nil, fmt.Errorf("failed to read root tree %s: %w", rootTreeHash, err)
	}

	subtree, err := rootTree.Tree(checkpointPath)
	if err != nil {
		return entries, nil //nolint:nilerr // Checkpoint doesn't exist yet
	}

	if err := checkpoint.FlattenTree(repo, subtree, checkpointPath, entries); err != nil {
		return nil, err
	}
	return entries, nil
}

// spliceCheckpointSubtree builds a tree from checkpoint-local entries and installs it
// at the correct shard location in the root tree using O(depth) tree surgery.
// basePath is like "a3/b2c4d5e6f7/" (with trailing slash).
// Duplicated from checkpoint.GitStore.spliceCheckpointSubtree.
func spliceCheckpointSubtree(repo *git.Repository, rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, basePath string, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
	relEntries := make(map[string]object.TreeEntry, len(entries))
	for path, entry := range entries {
		relPath := strings.TrimPrefix(path, basePath)
		if relPath == path {
			continue
		}
		relEntries[relPath] = entry
	}

	checkpointTreeHash, err := checkpoint.BuildTreeFromEntries(repo, relEntries)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to build checkpoint subtree: %w", err)
	}

	shardPrefix := string(checkpointID[:2])
	shardSuffix := string(checkpointID[2:])
	return checkpoint.UpdateSubtree(repo, rootTreeHash, []string{shardPrefix}, []object.TreeEntry{
		{Name: shardSuffix, Mode: filemode.Dir, Hash: checkpointTreeHash},
	}, checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.MergeKeepExisting})
}

// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
// Duplicated from checkpoint.readJSONFromBlob.
func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
	blob, err := repo.BlobObject(hash)
	if err != nil {
		return nil, fmt.Errorf("failed to get blob: %w", err)
	}

	reader, err := blob.Reader()
	if err != nil {
		return nil, fmt.Errorf("failed to get blob reader: %w", err)
	}
	defer reader.Close()

	var result T
	if err := json.NewDecoder(reader).Decode(&result); err != nil {
		return nil, fmt.Errorf("failed to decode: %w", err)
	}

	return &result, nil
}

// findSessionIndex returns the index of an existing session with the given ID,
// or the next available index if not found.
// Duplicated from checkpoint.GitStore.findSessionIndex.
func findSessionIndex(ctx context.Context, repo *git.Repository, basePath string, existingSummary *checkpoint.CheckpointSummary, entries map[string]object.TreeEntry, sessionID string) int {
	if existingSummary == nil {
		return 0
	}
	for i := range len(existingSummary.Sessions) {
		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
		if entry, exists := entries[path]; exists {
			meta, err := readJSONFromBlob[checkpoint.CommittedMetadata](repo, entry.Hash)
			if err != nil {
				logging.Warn(ctx, "failed to read session metadata during dedup check",
					slog.Int("session_index", i),
					slog.String("session_id", sessionID),
					slog.String("error", err.Error()),
				)
				continue
			}
			if meta.SessionID == sessionID {
				return i
			}
		}
	}
	return len(existingSummary.Sessions)
}

// writeCheckpointSummary writes the root metadata.json with aggregated stats from all sessions.
// Duplicated from checkpoint.GitStore.writeCheckpointSummary.
func writeCheckpointSummary(repo *git.Repository, opts checkpoint.WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, sessions []checkpoint.SessionFilePaths) error {
	checkpointsCount, filesTouched, tokenUsage, err :=
		reaggregateFromEntries(repo, basePath, len(sessions), entries)
	if err != nil {
		return fmt.Errorf("failed to aggregate session stats: %w", err)
	}

	summary := checkpoint.CheckpointSummary{
		CheckpointID:     opts.CheckpointID,
		CLIVersion:       versioninfo.Version,
		Strategy:         opts.Strategy,
		Branch:           opts.Branch,
		CheckpointsCount: checkpointsCount,
		FilesTouched:     filesTouched,
		Sessions:         sessions,
		TokenUsage:       tokenUsage,
	}

	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
	}
	metadataHash, err := checkpoint.CreateBlobFromContent(repo, metadataJSON)
	if err != nil {
		return err
	}
	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
		Name: basePath + paths.MetadataFileName,
		Mode: filemode.Regular,
		Hash: metadataHash,
	}
	return nil
}

// reaggregateFromEntries reads all session metadata from the entries map and
// reaggregates CheckpointsCount, FilesTouched, and TokenUsage.
// Duplicated from checkpoint.GitStore.reaggregateFromEntries.
func reaggregateFromEntries(repo *git.Repository, basePath string, sessionCount int, entries map[string]object.TreeEntry) (int, []string, *agent.TokenUsage, error) {
	var totalCount int
	var allFiles []string
	var totalTokens *agent.TokenUsage

	for i := range sessionCount {
		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
		entry, exists := entries[path]
		if !exists {
			return 0, nil, nil, fmt.Errorf("session %d metadata not found at %s", i, path)
		}
		meta, err := readJSONFromBlob[checkpoint.CommittedMetadata](repo, entry.Hash)
		if err != nil {
			return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
		}
		totalCount += meta.CheckpointsCount
		allFiles = mergeFilesTouched(allFiles, meta.FilesTouched)
		totalTokens = aggregateTokenUsage(totalTokens, meta.TokenUsage)
	}

	return totalCount, allFiles, totalTokens, nil
}

// aggregateTokenUsage sums two TokenUsage structs.
// Duplicated from checkpoint.aggregateTokenUsage.
func aggregateTokenUsage(a, b *agent.TokenUsage) *agent.TokenUsage {
	if a == nil && b == nil {
		return nil
	}
	result := &agent.TokenUsage{}
	if a != nil {
		result.InputTokens = a.InputTokens
		result.CacheCreationTokens = a.CacheCreationTokens
		result.CacheReadTokens = a.CacheReadTokens
		result.OutputTokens = a.OutputTokens
		result.APICallCount = a.APICallCount
	}
	if b != nil {
		result.InputTokens += b.InputTokens
		result.CacheCreationTokens += b.CacheCreationTokens
		result.CacheReadTokens += b.CacheReadTokens
		result.OutputTokens += b.OutputTokens
		result.APICallCount += b.APICallCount
	}
	return result
}

// mergeFilesTouched combines two file lists, removing duplicates.
// Duplicated from checkpoint.mergeFilesTouched.
func mergeFilesTouched(existing, additional []string) []string {
	seen := make(map[string]bool)
	var result []string

	for _, f := range existing {
		if !seen[f] {
			seen[f] = true
			result = append(result, f)
		}
	}
	for _, f := range additional {
		if !seen[f] {
			seen[f] = true
			result = append(result, f)
		}
	}

	sort.Strings(result)
	return result
}

// redactSummary returns a copy of the summary with text fields redacted.
// Duplicated from checkpoint.redactSummary.
func redactSummary(s *checkpoint.Summary) *checkpoint.Summary {
	if s == nil {
		return nil
	}
	return &checkpoint.Summary{
		Intent:    redact.String(s.Intent),
		Outcome:   redact.String(s.Outcome),
		Friction:  redactStringSlice(s.Friction),
		OpenItems: redactStringSlice(s.OpenItems),
		Learnings: checkpoint.LearningsSummary{
			Repo:     redactStringSlice(s.Learnings.Repo),
			Workflow: redactStringSlice(s.Learnings.Workflow),
			Code:     redactCodeLearnings(s.Learnings.Code),
		},
	}
}

// redactStringSlice applies redact.String to each element.
// Duplicated from checkpoint.redactStringSlice.
func redactStringSlice(ss []string) []string {
	if ss == nil {
		return nil
	}
	out := make([]string, len(ss))
	for i, s := range ss {
		out[i] = redact.String(s)
	}
	return out
}

// redactCodeLearnings redacts only the Finding field, preserving Path/Line/EndLine.
// Duplicated from checkpoint.redactCodeLearnings.
func redactCodeLearnings(cls []checkpoint.CodeLearning) []checkpoint.CodeLearning {
	if cls == nil {
		return nil
	}
	out := make([]checkpoint.CodeLearning, len(cls))
	for i, cl := range cls {
		out[i] = checkpoint.CodeLearning{
			Path:    cl.Path,
			Line:    cl.Line,
			EndLine: cl.EndLine,
			Finding: redact.String(cl.Finding),
		}
	}
	return out
}

